package com.lootlabels.dev;

import com.lootlabels.LootLabelsPlugin;
import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/**
 * Development only: starts a developer-mode client with only Loot Labels loaded.
 * Not part of the plugin.
 */
public class LootLabelsDevClient
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(LootLabelsPlugin.class);
		RuneLite.main(args);
	}
}

package com.lootlabels;

import java.awt.AlphaComposite;
import java.awt.BorderLayout;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.MouseInfo;
import java.awt.Point;
import java.awt.PointerInfo;
import java.awt.Polygon;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.event.ActionEvent;
import java.awt.event.KeyEvent;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.geom.Rectangle2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.util.function.Consumer;
import java.util.function.Supplier;
import javax.swing.AbstractAction;
import javax.swing.Icon;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.JScrollBar;
import javax.swing.JTextField;
import javax.swing.KeyStroke;
import javax.swing.Popup;
import javax.swing.PopupFactory;
import javax.swing.SwingConstants;
import javax.swing.Timer;
import javax.swing.border.Border;
import javax.swing.border.CompoundBorder;
import javax.swing.border.EmptyBorder;
import javax.swing.border.LineBorder;
import javax.swing.plaf.basic.BasicButtonUI;
import javax.swing.plaf.basic.BasicPopupMenuUI;
import javax.swing.plaf.basic.BasicScrollBarUI;
import javax.swing.plaf.basic.BasicTextFieldUI;
import javax.swing.text.AbstractDocument;
import javax.swing.text.AttributeSet;
import javax.swing.text.BadLocationException;
import javax.swing.text.DocumentFilter;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * Sidebar widgets drawn in grays only. They use the basic Swing UI classes so the look-and-feel can't paint
 * anything light over them.
 */
final class DarkUi
{
	static final Color PANEL = ColorScheme.DARK_GRAY_COLOR;
	static final Color CARD = ColorScheme.DARKER_GRAY_COLOR;
	static final Color FIELD = new Color(22, 22, 22);
	static final Color BUTTON = new Color(56, 56, 56);
	static final Color BUTTON_HOVER = new Color(72, 72, 72);
	static final Color BUTTON_PRESSED = new Color(46, 46, 46);
	static final Color MENU = new Color(24, 24, 24);
	static final Color LINE_LIT = new Color(175, 175, 175);
	static final Color LINE = new Color(64, 64, 64);
	static final Color TEXT = ColorScheme.LIGHT_GRAY_COLOR;
	static final Color TEXT_IDLE = new Color(130, 130, 130);
	static final Color TEXT_DIM = ColorScheme.MEDIUM_GRAY_COLOR;
	static final Color TEXT_BRIGHT = new Color(235, 235, 235);

	private DarkUi()
	{
	}

	// ---------------------------------------------------------------- buttons

	/** Strips the look-and-feel off a button: no focus ring, no rollover, no filled area. */
	private static <T extends JButton> T plain(T button)
	{
		button.setUI(new BasicButtonUI());
		button.setContentAreaFilled(false);
		button.setFocusPainted(false);
		button.setFocusable(false);
		button.setRolloverEnabled(false);
		return button;
	}

	/** Turns the button's foreground to {@code hover} while the mouse is over it, and back to {@code idle} after. */
	private static void tint(JButton button, Color hover, Supplier<Color> idle)
	{
		button.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				button.setForeground(hover);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				button.setForeground(idle.get());
			}
		});
	}

	static JButton button(String text)
	{
		final JButton button = plain(new JButton(text));
		button.setOpaque(true);
		button.setBackground(BUTTON);
		button.setForeground(TEXT_IDLE);
		button.setFont(FontManager.getRunescapeSmallFont());
		final Border idle = new CompoundBorder(new LineBorder(LINE), new EmptyBorder(2, 8, 2, 8));
		final Border lit = new CompoundBorder(new LineBorder(LINE_LIT), new EmptyBorder(2, 8, 2, 8));
		button.setBorder(idle);
		button.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				button.setBackground(BUTTON_HOVER);
				button.setForeground(TEXT_BRIGHT);
				button.setBorder(lit);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				button.setBackground(BUTTON);
				button.setForeground(TEXT_IDLE);
				button.setBorder(idle);
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				button.setBackground(BUTTON_PRESSED);
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				button.setBackground(button.contains(e.getPoint()) ? BUTTON_HOVER : BUTTON);
			}
		});
		return button;
	}

	/** A button that is just its icon. The icon is drawn in the foreground color: dim, then bright on hover. */
	static JButton iconButton(Icon icon)
	{
		return iconButton(icon, TEXT_BRIGHT);
	}

	static JButton iconButton(Icon icon, Color hover)
	{
		return iconButton(icon, hover, () -> TEXT_DIM);
	}

	/** {@code idle} is asked for each time the mouse leaves, so the resting color can change. */
	static JButton iconButton(Icon icon, Color hover, Supplier<Color> idle)
	{
		final JButton button = plain(new JButton(icon));
		button.setOpaque(false);
		button.setBorderPainted(false);
		button.setForeground(idle.get());
		button.setBorder(new EmptyBorder(0, 4, 0, 4));
		button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		tint(button, hover, idle);
		return button;
	}

	/** A row with a checkbox on its left. Clicking anywhere on the row flips it and reports the new state. */
	static JButton checkRow(String text, boolean selected, Consumer<Boolean> onChange)
	{
		final boolean[] on = {selected};
		final JButton row = plain(new JButton(text, checkIcon(selected))
		{
			@Override
			public Dimension getMinimumSize()
			{
				return new Dimension(0, super.getPreferredSize().height);
			}

			@Override
			public Dimension getMaximumSize()
			{
				return new Dimension(Integer.MAX_VALUE, super.getPreferredSize().height);
			}
		});
		row.setOpaque(false);
		row.setBorderPainted(false);
		row.setHorizontalAlignment(SwingConstants.LEFT);
		row.setIconTextGap(6);
		row.setFont(FontManager.getRunescapeSmallFont());
		row.setForeground(TEXT_IDLE);
		row.setBorder(new EmptyBorder(2, 2, 2, 2));
		row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		tint(row, TEXT_BRIGHT, () -> TEXT_IDLE);
		row.addActionListener(e ->
		{
			on[0] = !on[0];
			row.setIcon(checkIcon(on[0]));
			onChange.accept(on[0]);
		});
		return row;
	}

	// ------------------------------------------------------------------ hints

	/**
	 * Shows a small dark hint above the mouse pointer after the mouse has rested on the component for 0.6 seconds.
	 * (A per-component delay, so it doesn't change the tooltip behavior of the rest of RuneLite.)
	 */
	static void hoverHint(JComponent component, String text)
	{
		hoverHint(component, text, () -> true);
	}

	/** Like {@link #hoverHint(JComponent, String)}, but only shows when the condition holds at that moment. */
	static void hoverHint(JComponent component, String text, Supplier<Boolean> wanted)
	{
		final JLabel label = new JLabel(text);
		label.setOpaque(true);
		label.setBackground(MENU);
		label.setForeground(TEXT);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setBorder(new CompoundBorder(new LineBorder(LINE), new EmptyBorder(2, 6, 2, 6)));

		final Popup[] shown = new Popup[1];
		final Runnable hide = () ->
		{
			if (shown[0] != null)
			{
				shown[0].hide();
				shown[0] = null;
			}
		};

		final Timer delay = new Timer(600, e ->
		{
			if (!component.isShowing() || shown[0] != null || !wanted.get())
			{
				return;
			}

			final PointerInfo pointer = MouseInfo.getPointerInfo();
			if (pointer == null)
			{
				return;
			}

			// Centered above the mouse pointer, kept on the screen
			final Point at = pointer.getLocation();
			final Dimension size = label.getPreferredSize();
			final Rectangle screen = component.getGraphicsConfiguration().getBounds();
			final int x = Math.max(screen.x, Math.min(at.x - size.width / 2, screen.x + screen.width - size.width));
			final int y = at.y - size.height - 8 < screen.y ? at.y + 24 : at.y - size.height - 8;

			shown[0] = PopupFactory.getSharedInstance().getPopup(component, label, x, y);
			shown[0].show();
		});
		delay.setRepeats(false);

		component.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				delay.restart();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				delay.stop();
				hide.run();
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				delay.stop();
				hide.run();
			}
		});

		// The list is rebuilt now and then; don't leave a hint behind for a button that is gone
		component.addHierarchyListener(e ->
		{
			if (!component.isShowing())
			{
				delay.stop();
				hide.run();
			}
		});
	}

	// ------------------------------------------------------------------ icons

	/** Draws an icon. {@code c} is the component it is painted on, for its foreground color. */
	private interface IconPainter
	{
		void paint(Graphics2D g2, Component c);
	}

	/**
	 * A size by size icon. The painter gets antialiased graphics, already moved to the icon's corner, with a 1px
	 * round stroke in the component's foreground color.
	 */
	private static Icon icon(int size, IconPainter painter)
	{
		return new Icon()
		{
			@Override
			public int getIconWidth()
			{
				return size;
			}

			@Override
			public int getIconHeight()
			{
				return size;
			}

			@Override
			public void paintIcon(Component c, Graphics g, int x, int y)
			{
				final Graphics2D g2 = (Graphics2D) g.create();
				g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				g2.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
				g2.setColor(c.getForeground());
				g2.setStroke(new BasicStroke(1f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g2.translate(x, y);
				painter.paint(g2, c);
				g2.dispose();
			}
		};
	}

	/** Straight lines through the given x, y pairs, optionally closed back to the start. */
	private static Path2D path(boolean closed, double... xy)
	{
		final Path2D.Float path = new Path2D.Float();
		path.moveTo(xy[0], xy[1]);
		for (int i = 2; i < xy.length; i += 2)
		{
			path.lineTo(xy[i], xy[i + 1]);
		}
		if (closed)
		{
			path.closePath();
		}
		return path;
	}

	/** Several outlines as one path, so strokes that overlap don't draw twice as dark where they meet. */
	private static Path2D join(Path2D... parts)
	{
		final Path2D.Float joined = new Path2D.Float();
		for (Path2D part : parts)
		{
			joined.append(part, false);
		}
		return joined;
	}

	private static boolean isDim(Component c)
	{
		return TEXT_DIM.equals(c.getForeground());
	}

	private static AlphaComposite fadeWhenDim(Component c)
	{
		return AlphaComposite.SrcOver.derive(isDim(c) ? 0.65f : 1f);
	}

	/** The same icon drawn as a size by size square. */
	static Icon scaled(Icon source, int size)
	{
		return icon(size, (g2, c) ->
		{
			g2.scale((double) size / source.getIconWidth(), (double) size / source.getIconHeight());
			source.paintIcon(c, g2, 0, 0);
		});
	}

	/** An octothorpe (#), for the quantity condition. */
	static Icon hashIcon()
	{
		return icon(14, (g2, c) ->
		{
			g2.draw(path(false, 5.5, 1.5, 4, 12.5));
			g2.draw(path(false, 10.5, 1.5, 9, 12.5));
			g2.draw(path(false, 2, 5, 12.5, 5));
			g2.draw(path(false, 1.5, 9, 12, 9));
		});
	}

	/** A hand holding up a stack of coins, like the Grand Exchange logo without its circle. */
	static Icon geIcon()
	{
		return icon(14, (g2, c) ->
		{
			g2.draw(new Rectangle2D.Float(5f, 1f, 5f, 8.5f));
			g2.draw(path(false, 5, 3.8, 10, 3.8));
			g2.draw(path(false, 5, 6.6, 10, 6.6));
			g2.draw(path(true, 1, 11.2, 3.6, 9.3, 8.5, 9.3, 10.2, 10.2, 12.8, 10.4, 12, 12.2, 4, 12.8));
		});
	}

	/** A flask above a row of coins, like the High Level Alchemy icon, for the high alchemy condition. */
	static Icon haIcon()
	{
		return icon(14, (g2, c) ->
		{
			g2.draw(join(
				path(false, 5.7, 0.8, 8.3, 0.8),
				path(false, 6.2, 0.8, 6.2, 4.2, 3.4, 9),
				path(false, 7.8, 0.8, 7.8, 4.2, 10.6, 9)));
			g2.draw(new Ellipse2D.Float(0.7f, 9f, 3.9f, 3.9f));
			g2.draw(new Ellipse2D.Float(5.1f, 9f, 3.9f, 3.9f));
			g2.draw(new Ellipse2D.Float(9.5f, 9f, 3.9f, 3.9f));
		});
	}

	/** Stacked layers, for the stackable condition. */
	static Icon stackIcon()
	{
		return icon(14, (g2, c) ->
		{
			g2.draw(path(true, 7, 1.5, 12.8, 4.6, 7, 7.7, 1.2, 4.6));
			g2.draw(path(false, 1.2, 7.2, 7, 10.3, 12.8, 7.2));
			g2.draw(path(false, 1.2, 9.8, 7, 12.9, 12.8, 9.8));
		});
	}

	/** A small rounded square filled with the given color, outlined in the foreground color. */
	static Icon swatchIcon(int rgb)
	{
		return icon(14, (g2, c) ->
		{
			final RoundRectangle2D.Float square = new RoundRectangle2D.Float(1.5f, 1.5f, 11f, 11f, 3f, 3f);
			g2.setComposite(fadeWhenDim(c));
			g2.setColor(new Color(rgb & 0xFFFFFF));
			g2.fill(square);
			g2.setColor(c.getForeground());
			g2.draw(square);
		});
	}

	/** Shows an image (a rank icon) as a button icon. */
	static Icon imageIcon(BufferedImage image)
	{
		return icon(14, (g2, c) ->
		{
			g2.setComposite(fadeWhenDim(c));
			g2.drawImage(image, (14 - image.getWidth()) / 2, (14 - image.getHeight()) / 2, null);
		});
	}

	/** A framed picture with a sun and mountains. */
	static Icon pictureIcon()
	{
		return icon(14, (g2, c) ->
		{
			g2.draw(new RoundRectangle2D.Float(1.5f, 2.5f, 11f, 9f, 2f, 2f));
			g2.draw(new Ellipse2D.Float(4f, 4.5f, 2f, 2f));
			g2.draw(path(false, 2.5, 10, 5.5, 7.5, 7.5, 9.2, 9, 8, 11.5, 10));
		});
	}

	/** An arrow leaving a tray (export), or entering one (import). */
	static Icon transferIcon(boolean export)
	{
		return icon(12, (g2, c) ->
		{
			final double tip = export ? 1 : 8;
			final double tail = export ? 8 : 1;
			final double wing = export ? 3.8 : 5.2;
			g2.draw(path(false, 1.5, 8, 1.5, 11, 10.5, 11, 10.5, 8));
			g2.draw(join(path(false, 6, tail, 6, tip), path(false, 3.2, wing, 6, tip, 8.8, wing)));
		});
	}

	/** A small box, with a tick in it when checked. */
	static Icon checkIcon(boolean checked)
	{
		return icon(12, (g2, c) ->
		{
			g2.draw(new Rectangle2D.Float(0.5f, 0.5f, 11, 11));
			if (checked)
			{
				g2.setStroke(new BasicStroke(1.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g2.draw(path(false, 3, 6.3, 5.2, 8.5, 9, 3.6));
			}
		});
	}

	/** A plus sign, or an x when cross is true. */
	static Icon symbolIcon(boolean cross)
	{
		return icon(12, (g2, c) ->
		{
			g2.setStroke(new BasicStroke(1.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g2.translate(6, 6);
			if (cross)
			{
				g2.rotate(Math.PI / 4);
			}
			g2.drawLine(-4, 0, 4, 0);
			g2.drawLine(0, -4, 0, 4);
		});
	}

	/** A small triangle: pointing down when expanded, right when collapsed. */
	static Icon arrowIcon(boolean expanded)
	{
		return icon(10, (g2, c) ->
		{
			g2.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_DEFAULT);
			g2.fillPolygon(expanded
				? new Polygon(new int[]{0, 8, 4}, new int[]{2, 2, 7}, 3)
				: new Polygon(new int[]{2, 2, 7}, new int[]{0, 8, 4}, 3));
		});
	}

	// ----------------------------------------------------------------- fields

	/** The smaller font used inside the condition editor rows. */
	static Font editorFont()
	{
		return FontManager.getRunescapeSmallFont().deriveFont(12f);
	}

	/** Lets a text field take only digits, commas, periods and the letters k, m and b. Anything else is dropped. */
	static void limitToAmounts(JTextField field)
	{
		((AbstractDocument) field.getDocument()).setDocumentFilter(new DocumentFilter()
		{
			@Override
			public void insertString(FilterBypass fb, int offset, String text, AttributeSet attrs)
				throws BadLocationException
			{
				super.insertString(fb, offset, onlyAmountCharacters(text), attrs);
			}

			@Override
			public void replace(FilterBypass fb, int offset, int length, String text, AttributeSet attrs)
				throws BadLocationException
			{
				super.replace(fb, offset, length, onlyAmountCharacters(text), attrs);
			}
		});
	}

	private static String onlyAmountCharacters(String text)
	{
		if (text == null)
		{
			return null;
		}

		final StringBuilder kept = new StringBuilder();
		for (char c : text.toCharArray())
		{
			final char lower = Character.toLowerCase(c);
			if ((c >= '0' && c <= '9') || c == ',' || c == '.' || lower == 'k' || lower == 'm' || lower == 'b')
			{
				kept.append(lower);
			}
		}
		return kept.toString();
	}

	static JTextField textField()
	{
		final JTextField field = new JTextField();
		field.setUI(new BasicTextFieldUI());
		field.setBackground(FIELD);
		field.setForeground(TEXT_BRIGHT);
		field.setCaretColor(TEXT_BRIGHT);
		field.setSelectionColor(new Color(90, 90, 90));
		field.setSelectedTextColor(Color.WHITE);
		field.setFont(FontManager.getRunescapeSmallFont());
		field.setBorder(new CompoundBorder(new LineBorder(LINE), new EmptyBorder(3, 5, 3, 5)));
		return field;
	}

	// ------------------------------------------------------------------ menus

	static JPopupMenu popupMenu()
	{
		final JPopupMenu menu = new JPopupMenu();
		menu.setUI(new BasicPopupMenuUI());
		menu.setOpaque(true);
		menu.setBackground(MENU);
		menu.setBorder(new LineBorder(LINE));
		return menu;
	}

	/**
	 * A row in a popup menu. It is a plain label rather than a JMenuItem, so clicking it doesn't close the popup
	 * by itself, which lets a row turn into a "SURE?" confirmation.
	 */
	static final class MenuRow extends JLabel
	{
		static final Color DANGER = new Color(214, 74, 74);

		private final Runnable onClick;
		private boolean danger;

		MenuRow(String text, Runnable onClick)
		{
			super(text);
			this.onClick = onClick;

			setOpaque(true);
			setBackground(MENU);
			setForeground(TEXT_IDLE);
			setFont(FontManager.getRunescapeSmallFont());
			setBorder(new EmptyBorder(4, 10, 4, 10));
			setHorizontalAlignment(SwingConstants.CENTER);
			setAlignmentX(Component.LEFT_ALIGNMENT);
			setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

			addMouseListener(new MouseAdapter()
			{
				@Override
				public void mouseEntered(MouseEvent e)
				{
					setBackground(BUTTON);
					setForeground(danger ? DANGER : TEXT_BRIGHT);
				}

				@Override
				public void mouseExited(MouseEvent e)
				{
					setBackground(MENU);
					setForeground(danger ? DANGER : TEXT_IDLE);
				}

				@Override
				public void mousePressed(MouseEvent e)
				{
					MenuRow.this.onClick.run();
				}
			});
		}

		void setDanger(boolean danger)
		{
			this.danger = danger;
			setForeground(danger ? DANGER : TEXT_IDLE);
		}

		@Override
		public Dimension getMaximumSize()
		{
			return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
		}
	}

	/** A card: a dark box with a thin outline, laid out with a BorderLayout. */
	static JPanel card()
	{
		final JPanel card = new JPanel(new BorderLayout());
		card.setBackground(CARD);
		card.setBorder(new CompoundBorder(new LineBorder(new Color(52, 52, 52)), new EmptyBorder(6, 6, 6, 6)));
		return card;
	}

	/** Runs the action when Escape is pressed in the component. */
	static void onEscape(JComponent component, Runnable action)
	{
		component.getInputMap(JComponent.WHEN_FOCUSED).put(KeyStroke.getKeyStroke(KeyEvent.VK_ESCAPE, 0), "lootLabels.cancel");
		component.getActionMap().put("lootLabels.cancel", new AbstractAction()
		{
			@Override
			public void actionPerformed(ActionEvent e)
			{
				action.run();
			}
		});
	}

	/** A thin gray scrollbar without arrow buttons. */
	static void styleScrollBar(JScrollBar bar)
	{
		bar.setPreferredSize(new Dimension(8, 0));
		bar.setUnitIncrement(16);
		bar.setBackground(PANEL);
		bar.setUI(new BasicScrollBarUI()
		{
			@Override
			protected void configureScrollBarColors()
			{
				super.configureScrollBarColors();
				final Color thumb = new Color(74, 74, 74);
				thumbColor = thumb;
				thumbHighlightColor = thumb;
				thumbDarkShadowColor = thumb;
				thumbLightShadowColor = thumb;
				trackColor = PANEL;
				trackHighlightColor = PANEL;
			}

			@Override
			protected void paintThumb(Graphics g, JComponent c, Rectangle thumbBounds)
			{
				// Nothing to scroll: leave the (invisible) track empty
				if (scrollbar.getVisibleAmount() >= scrollbar.getMaximum() - scrollbar.getMinimum())
				{
					return;
				}
				super.paintThumb(g, c, thumbBounds);
			}

			@Override
			protected JButton createDecreaseButton(int orientation)
			{
				return emptyButton();
			}

			@Override
			protected JButton createIncreaseButton(int orientation)
			{
				return emptyButton();
			}

			private JButton emptyButton()
			{
				final JButton button = new JButton();
				button.setPreferredSize(new Dimension(0, 0));
				button.setMinimumSize(new Dimension(0, 0));
				button.setMaximumSize(new Dimension(0, 0));
				return button;
			}
		});
	}
}

package com.lootlabels;

import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;
import java.util.function.IntConsumer;
import javax.swing.JComponent;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;

/**
 * Lets the user drag one of a column of components up or down to reorder it, and tells apart a drag from a click.
 * Attach one instance to every component that should act as the handle (e.g. a row and the label in it).
 *
 * While dragging, a thin line shows where the component would land. Nothing moves until the mouse is released, at
 * which point the owner is told the new position and is expected to rebuild the column.
 */
final class DragReorder extends MouseAdapter
{
	private static final int THRESHOLD = 4; // pixels the mouse has to move before a press becomes a drag

	private final JComponent container;
	private final List<JComponent> siblings;
	private final int index;
	private final IntConsumer onMove;
	private final Consumer<MouseEvent> onClick;
	private final Consumer<MouseEvent> onPopup;

	private boolean pressed;
	private boolean dragging;
	private int pressY;
	private int[] middles;
	private int target;
	private JPanel marker;

	/**
	 * @param container the panel that directly holds the siblings
	 * @param siblings everything that can be reordered together, top to bottom (including the dragged component)
	 * @param index this component's place in siblings
	 * @param onMove told the place (among all the siblings) the component was dropped at
	 * @param onClick told about a left click that wasn't a drag
	 * @param onPopup told about a right click (or whatever opens a context menu), or null
	 */
	DragReorder(JComponent container, List<JComponent> siblings, int index, IntConsumer onMove,
		Consumer<MouseEvent> onClick, Consumer<MouseEvent> onPopup)
	{
		this.container = container;
		this.siblings = siblings;
		this.index = index;
		this.onMove = onMove;
		this.onClick = onClick;
		this.onPopup = onPopup;
	}

	void attach(Component... components)
	{
		for (Component component : components)
		{
			component.addMouseListener(this);
			component.addMouseMotionListener(this);
		}
	}

	@Override
	public void mousePressed(MouseEvent e)
	{
		if (e.isPopupTrigger() || SwingUtilities.isRightMouseButton(e))
		{
			if (onPopup != null)
			{
				onPopup.accept(e);
			}
			return;
		}

		if (SwingUtilities.isLeftMouseButton(e))
		{
			pressed = true;
			dragging = false;
			pressY = containerY(e);
		}
	}

	@Override
	public void mouseDragged(MouseEvent e)
	{
		if (!pressed)
		{
			return;
		}

		final int y = containerY(e);
		if (!dragging)
		{
			if (Math.abs(y - pressY) < THRESHOLD)
			{
				return;
			}
			startDragging();
		}

		// The new place is the number of the other siblings that are above the mouse
		int above = 0;
		for (int i = 0; i < middles.length; i++)
		{
			if (i != index && middles[i] < y)
			{
				above++;
			}
		}

		if (marker == null || above != target)
		{
			target = above;
			showMarker();
		}
	}

	@Override
	public void mouseReleased(MouseEvent e)
	{
		if (!pressed)
		{
			return;
		}
		pressed = false;

		if (dragging)
		{
			dragging = false;
			hideMarker();
			container.setCursor(null);
			if (target != index)
			{
				onMove.accept(target);
			}
		}
		else if (e.getComponent().contains(e.getPoint()))
		{
			onClick.accept(e);
		}
	}

	private int containerY(MouseEvent e)
	{
		return SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), container).y;
	}

	private void startDragging()
	{
		dragging = true;
		target = index;

		// Positions are taken now, before the marker moves anything
		middles = new int[siblings.size()];
		for (int i = 0; i < middles.length; i++)
		{
			final JComponent sibling = siblings.get(i);
			middles[i] = sibling.getY() + sibling.getHeight() / 2;
		}
		container.setCursor(Cursor.getPredefinedCursor(Cursor.MOVE_CURSOR));
	}

	private void showMarker()
	{
		hideMarker();

		final List<JComponent> others = new ArrayList<>(siblings);
		others.remove(index);
		if (others.isEmpty())
		{
			return;
		}

		marker = new JPanel();
		marker.setBackground(DarkUi.LINE_LIT);
		marker.setPreferredSize(new Dimension(0, 2));
		marker.setMaximumSize(new Dimension(Integer.MAX_VALUE, 2));
		marker.setAlignmentX(Component.LEFT_ALIGNMENT);

		final int at = target < others.size()
			? container.getComponentZOrder(others.get(target))
			: container.getComponentZOrder(others.get(others.size() - 1)) + 1;
		container.add(marker, at);
		container.revalidate();
		container.repaint();
	}

	private void hideMarker()
	{
		if (marker != null)
		{
			container.remove(marker);
			marker = null;
			container.revalidate();
			container.repaint();
		}
	}
}

package com.lootlabels;

import java.util.List;
import lombok.Getter;
import lombok.Setter;
import net.runelite.api.TileItem;

/** An item lying on the ground along with the text drawn for it. */
class GroundLabel
{
	@Getter
	private final TileItem item;

	/** The item's name as the game shows it. */
	@Getter
	private final String name;

	/** The name in the form used to look it up in the label groups. */
	@Getter
	private final String key;

	/** How many are in the pile. Kept here because it can change while the item is on the ground. */
	@Getter
	@Setter
	private int quantity;

	/** Prices of one item, and whether the item stacks. They don't change, so they are looked up once. */
	private final long gePrice;
	private final long haPrice;

	@Getter
	private final boolean stackable;

	/** The game tick the item was first seen on the ground, for working out how far through its time it is. */
	@Getter
	private final int spawnTick;

	/**
	 * The label whose timer state this one uses: itself, or for a label standing for a pile, the real label of the
	 * item that despawns first. (Pile labels are rebuilt every frame, so they can't keep state of their own.)
	 */
	private GroundLabel source;

	/**
	 * For the despawn timer in seconds: when the item is expected to despawn (System.nanoTime(), 0 until known), and
	 * the game tick that estimate was last adjusted on.
	 */
	@Getter
	@Setter
	private long deadlineNanos;

	@Getter
	@Setter
	private int syncedTick;

	GroundLabel target()
	{
		return source == null ? this : source;
	}

	GroundLabel(TileItem item, String name, long gePrice, long haPrice, boolean stackable, int spawnTick)
	{
		this.spawnTick = spawnTick;
		this.item = item;
		this.name = name;
		this.key = LabelGroupManager.normalize(name);
		this.quantity = item.getQuantity();
		this.gePrice = gePrice;
		this.haPrice = haPrice;
		this.stackable = stackable;
	}

	/** One label standing for several of the same item lying on a tile: same item, the quantities added together. */
	static GroundLabel merged(List<GroundLabel> same)
	{
		// The one that despawns first stands for the pile when showing despawn times
		GroundLabel first = same.get(0);
		int quantity = 0;
		for (GroundLabel label : same)
		{
			quantity += label.quantity;
			if (label.item.getDespawnTime() < first.item.getDespawnTime())
			{
				first = label;
			}
		}

		final GroundLabel merged = new GroundLabel(first.item, first.name, first.gePrice, first.haPrice,
			first.stackable, first.spawnTick);
		merged.quantity = quantity;
		merged.source = first.target();
		return merged;
	}

	/**
	 * The text drawn for the item: its name and the amount when there is more than one, and its value when
	 * that is turned on in the settings.
	 */
	String getText(LootLabelsConfig config, boolean showValue)
	{
		// A stack of a stackable item reads "Name (100)"; several of a non-stackable item read "Name x100"
		final String base = quantity <= 1 ? name : (stackable ? name + " (" + abbreviate(quantity) + ")" : name + " x" + abbreviate(quantity));
		if (!showValue)
		{
			return base;
		}

		final long ge = getGeTotal();
		final long ha = getHaTotal();
		final boolean verbose = config.displayStyle() == LootLabelsConfig.DisplayStyle.VERBOSE;
		switch (config.valueDisplay())
		{
			case GRAND_EXCHANGE:
				return ge > 0 ? base + single("GE", ge, verbose) : base;
			case HIGH_ALCHEMY:
				return ha > 0 ? base + single("HA", ha, verbose) : base;
			case BOTH:
				if (ge <= 0 && ha <= 0)
				{
					return base;
				}
				return verbose
					? base + " [GE: " + abbreviate(ge) + "] [HA: " + abbreviate(ha) + "]"
					: base + " [" + abbreviate(ge) + "/" + abbreviate(ha) + "]";
			default:
				if (Math.max(ge, ha) <= 0)
				{
					return base;
				}
				return ge >= ha ? base + single("GE", ge, verbose) : base + single("HA", ha, verbose);
		}
	}

	private static String single(String kind, long value, boolean verbose)
	{
		return verbose ? " [" + kind + ": " + abbreviate(value) + "]" : " [" + abbreviate(value) + "]";
	}

	/**
	 * For quantities and values. Under 1,000 it is the plain number (800); from 1,000 up it is K, M or B with one
	 * decimal (1.5K, 2M).
	 */
	static String abbreviate(long value)
	{
		if (value < 1000)
		{
			return String.valueOf(value);
		}

		final String[] units = {"K", "M", "B"};
		double scaled = value / 1000.0;
		int unit = 0;
		// 999,950 rounds to 1000.0K, which reads better as 1M
		while (unit < units.length - 1 && Math.round(scaled * 10) / 10.0 >= 1000)
		{
			scaled /= 1000;
			unit++;
		}

		final double rounded = Math.round(scaled * 10) / 10.0;
		final String number = rounded == Math.floor(rounded) ? String.valueOf((long) rounded) : String.valueOf(rounded);
		return number + units[unit];
	}

	/** The Grand Exchange value of the whole pile. */
	long getGeTotal()
	{
		return gePrice * quantity;
	}

	/** The high alchemy value of the whole pile. */
	long getHaTotal()
	{
		return haPrice * quantity;
	}
}

package com.lootlabels;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import java.util.ArrayList;
import java.util.List;
import lombok.extern.slf4j.Slf4j;

/** Turns groups into shareable JSON, and reads other people's JSON back into groups that are safe to add. */
@Slf4j
final class GroupTransfer
{
	private GroupTransfer()
	{
	}

	static String export(Gson gson, List<LabelGroup> selected)
	{
		final JsonObject root = new JsonObject();
		root.addProperty("format", "loot-labels");
		root.addProperty("version", 1);
		final JsonElement tree = gson.toJsonTree(selected);
		for (JsonElement element : tree.getAsJsonArray())
		{
			// Whether a group is open in the sidebar or switched on is personal, so neither is shared
			element.getAsJsonObject().remove("collapsed");
			element.getAsJsonObject().remove("enabled");
		}
		root.add("groups", tree);
		return gson.toJson(root);
	}

	/**
	 * Reads groups out of text that was exported by {@link #export} (or a bare list of groups, or a single group).
	 * Anything that isn't a group is skipped, and what is kept is cleaned up, so the result is safe to add.
	 */
	static List<LabelGroup> parse(Gson gson, String text)
	{
		final List<LabelGroup> found = new ArrayList<>();
		try
		{
			for (JsonElement element : groupElements(gson.fromJson(text.trim(), JsonElement.class)))
			{
				if (element != null && element.isJsonObject())
				{
					final LabelGroup group = sanitize(gson.fromJson(element, LabelGroup.class));
					if (group != null)
					{
						found.add(group);
					}
				}
			}
		}
		catch (JsonParseException | IllegalStateException | ClassCastException e)
		{
			log.debug("Could not read imported label groups", e);
		}
		return found;
	}

	/** The group objects in an export envelope, a bare array, or a lone group. */
	private static List<JsonElement> groupElements(JsonElement root)
	{
		final List<JsonElement> elements = new ArrayList<>();
		if (root != null && root.isJsonArray())
		{
			root.getAsJsonArray().forEach(elements::add);
		}
		else if (root != null && root.isJsonObject())
		{
			final JsonObject object = root.getAsJsonObject();
			final JsonElement list = object.get("groups");
			if (list != null && list.isJsonArray())
			{
				list.getAsJsonArray().forEach(elements::add);
			}
			else if (object.has("entries") || object.has("items"))
			{
				elements.add(object);
			}
		}
		return elements;
	}

	/** A clean copy of a group read from somebody else's JSON, or null if it isn't usable. */
	private static LabelGroup sanitize(LabelGroup source)
	{
		if (source == null)
		{
			return null;
		}
		source.migrate();

		String name = source.getName() == null ? "" : source.getName().trim();
		if (name.length() > 60)
		{
			name = name.substring(0, 60).trim();
		}

		final LabelGroup group = new LabelGroup(name.isEmpty() ? "Imported" : name);
		group.setEnabled(false);
		group.setCollapsed(true);
		group.setColor(source.getColor() & 0xFFFFFF);
		group.setColorChosen(source.hasChosenColor());
		for (String id : RankIcons.IDS)
		{
			if (id.equals(source.getIcon()))
			{
				group.setIcon(id);
				break;
			}
		}

		for (ItemEntry entry : source.getEntries())
		{
			final String key = LabelGroupManager.normalize(entry.getName());
			if (key.isEmpty())
			{
				continue;
			}
			final ItemEntry copy = new ItemEntry(LabelGroupManager.capitalize(key));
			if (entry.getConditions() != null && !entry.getConditions().isEmpty())
			{
				copy.setConditions(entry.getConditions().copy());
			}
			group.getEntries().add(copy);
		}
		return group;
	}
}

package com.lootlabels;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Locale;
import java.util.OptionalLong;

/**
 * Conditions an item has to meet for a group's style to apply to it: its quantity, its Grand Exchange value, its
 * high alchemy value and whether it stacks. Every condition that is set has to hold. Values are for the whole pile
 * on the ground (price times quantity). Saved as JSON with the group, so the field names are part of the format.
 *
 * Instances are edited only by replacing whole conditions, and the overlay reads copies, never the live object.
 */
final class ItemConditions
{
	enum Type
	{
		QUANTITY, GE_VALUE, HA_VALUE, STACKABLE
	}

	enum Op
	{
		EQ("="), GT(">"), LT("<"), GE(">="), LE("<=");

		private final String symbol;

		Op(String symbol)
		{
			this.symbol = symbol;
		}

		/** Plain ASCII form, used to look up the drawn symbol. */
		String symbol()
		{
			return symbol;
		}

		boolean test(long actual, long expected)
		{
			switch (this)
			{
				case EQ:
					return actual == expected;
				case GT:
					return actual > expected;
				case LT:
					return actual < expected;
				case GE:
					return actual >= expected;
				default:
					return actual <= expected;
			}
		}
	}

	static final class Comparison
	{
		private final Op op;
		private final long value;

		Comparison(Op op, long value)
		{
			this.op = op;
			this.value = value;
		}

		Op getOp()
		{
			return op;
		}

		long getValue()
		{
			return value;
		}

		boolean test(long actual)
		{
			return op.test(actual, value);
		}

		boolean sameAs(Comparison other)
		{
			return other != null && op == other.op && value == other.value;
		}
	}

	private Comparison quantity;
	private Comparison geValue;
	private Comparison haValue;
	private Boolean stackable;

	boolean has(Type type)
	{
		return type == Type.STACKABLE ? stackable != null : getComparison(type) != null;
	}

	boolean isEmpty()
	{
		return quantity == null && geValue == null && haValue == null && stackable == null;
	}

	Comparison getComparison(Type type)
	{
		switch (type)
		{
			case QUANTITY:
				return quantity;
			case GE_VALUE:
				return geValue;
			case HA_VALUE:
				return haValue;
			default:
				return null;
		}
	}

	void setComparison(Type type, Comparison comparison)
	{
		switch (type)
		{
			case QUANTITY:
				quantity = comparison;
				break;
			case GE_VALUE:
				geValue = comparison;
				break;
			case HA_VALUE:
				haValue = comparison;
				break;
			default:
				break;
		}
	}

	Boolean getStackable()
	{
		return stackable;
	}

	void setStackable(Boolean stackable)
	{
		this.stackable = stackable;
	}

	void clear(Type type)
	{
		if (type == Type.STACKABLE)
		{
			stackable = null;
		}
		else
		{
			setComparison(type, null);
		}
	}

	ItemConditions copy()
	{
		final ItemConditions copy = new ItemConditions();
		copy.quantity = quantity;
		copy.geValue = geValue;
		copy.haValue = haValue;
		copy.stackable = stackable;
		return copy;
	}

	boolean matches(GroundLabel label)
	{
		return (quantity == null || quantity.test(label.getQuantity()))
			&& (geValue == null || geValue.test(label.getGeTotal()))
			&& (haValue == null || haValue.test(label.getHaTotal()))
			&& (stackable == null || stackable == label.isStackable());
	}

	/** Reads a whole number, allowing commas and the k, m and b suffixes (e.g. "2.5m"). */
	static OptionalLong parseAmount(String text)
	{
		String t = text.trim().toLowerCase(Locale.ROOT).replace(",", "").replace("_", "").replace(" ", "");
		if (t.isEmpty())
		{
			return OptionalLong.empty();
		}

		long multiplier = 1;
		final char last = t.charAt(t.length() - 1);
		if (last == 'k')
		{
			multiplier = 1_000L;
		}
		else if (last == 'm')
		{
			multiplier = 1_000_000L;
		}
		else if (last == 'b')
		{
			multiplier = 1_000_000_000L;
		}

		try
		{
			if (multiplier == 1)
			{
				final long value = Long.parseLong(t);
				return value >= 0 ? OptionalLong.of(value) : OptionalLong.empty();
			}

			final BigDecimal value = new BigDecimal(t.substring(0, t.length() - 1)).multiply(BigDecimal.valueOf(multiplier));
			return value.signum() >= 0
				? OptionalLong.of(value.setScale(0, RoundingMode.HALF_UP).longValueExact())
				: OptionalLong.empty();
		}
		catch (NumberFormatException | ArithmeticException e)
		{
			return OptionalLong.empty();
		}
	}

	/** The full number with commas: 1500000 is "1,500,000". */
	static String formatAmount(long value)
	{
		return String.format(Locale.US, "%,d", value);
	}
}

package com.lootlabels;

/**
 * One line in a group: an item name (which may use * as a wildcard) and, optionally, the conditions the item has
 * to meet for this line to apply. A group can have several lines for the same name, each with its own conditions.
 * Saved as JSON with the group, so the field names are part of the format.
 */
final class ItemEntry
{
	private String name = "";

	/** Null when the line always applies. */
	private ItemConditions conditions;

	ItemEntry()
	{
	}

	ItemEntry(String name)
	{
		this.name = name;
	}

	String getName()
	{
		return name == null ? "" : name;
	}

	void setName(String name)
	{
		this.name = name;
	}

	ItemConditions getConditions()
	{
		return conditions;
	}

	void setConditions(ItemConditions conditions)
	{
		this.conditions = conditions;
	}
}

package com.lootlabels;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import lombok.Getter;
import lombok.Setter;

/**
 * A named set of item names that can be switched on and off together. Saved as JSON in the plugin's config,
 * so the field names here are part of the saved format.
 */
class LabelGroup
{
	static final int DEFAULT_COLOR = 0x000000;

	@Getter
	@Setter
	private String name = "";

	@Getter
	@Setter
	private boolean enabled = true;

	@Getter
	@Setter
	private boolean collapsed;

	/** The color of this group's labels, as 0xRRGGBB. */
	@Getter
	@Setter
	private int color = DEFAULT_COLOR;

	/** Whether the user has picked a color (as opposed to the default black). */
	@Setter
	private boolean colorChosen;

	/**
	 * The rank icon drawn left of the text in this group's labels (see {@link RankIcons}), or "" for none.
	 */
	@Getter
	@Setter
	private String icon = "";

	/** The lines of this group, top to bottom. */
	@Getter
	private List<ItemEntry> entries = new ArrayList<>();

	/**
	 * Only read from groups saved before entries existed (names, and conditions by name). {@link #migrate()} turns
	 * them into entries and clears them, so they are not saved again.
	 */
	private List<String> items;
	private Map<String, ItemConditions> conditions;

	LabelGroup()
	{
	}

	LabelGroup(String name)
	{
		this.name = name;
	}

	/** Call after reading a group from JSON: upgrades the old format and drops anything unusable. */
	void migrate()
	{
		if (entries == null)
		{
			entries = new ArrayList<>();
		}
		entries.removeIf(entry -> entry == null);

		if (items != null)
		{
			for (String item : items)
			{
				if (item == null)
				{
					continue;
				}
				final ItemEntry entry = new ItemEntry(item);
				final ItemConditions old = conditions == null ? null : conditions.get(LabelGroupManager.normalize(item));
				if (old != null && !old.isEmpty())
				{
					entry.setConditions(old);
				}
				entries.add(entry);
			}
		}
		items = null;
		conditions = null;
	}

	boolean hasChosenColor()
	{
		return colorChosen || color != DEFAULT_COLOR;
	}

	boolean hasChosenIcon()
	{
		return icon != null && !icon.isEmpty();
	}
}

package com.lootlabels;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Owns the label groups: loads and saves them, and answers "should this item get a label?".
 *
 * Groups are only changed from the sidebar panel (Swing thread), while the overlay asks about visibility every
 * frame on the client thread, so the overlay reads an immutable snapshot of the rules instead of the groups.
 */
@Slf4j
@Singleton
class LabelGroupManager
{
	private static final String CONFIG_KEY = "groups";

	private final ConfigManager configManager;
	private final Gson gson;
	private final List<LabelGroup> groups = new ArrayList<>();
	private volatile Rules rules = new Rules(new ArrayList<>());

	@Inject
	LabelGroupManager(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	/** Item names are compared ignoring case and surrounding spaces. */
	static String normalize(String name)
	{
		return name == null ? "" : name.trim().toLowerCase(Locale.ROOT);
	}

	/** Item names are stored with the first letter capitalized and everything else lowercase. */
	static String capitalize(String name)
	{
		final String key = normalize(name);
		return key.isEmpty() ? key : key.substring(0, 1).toUpperCase(Locale.ROOT) + key.substring(1);
	}

	synchronized void load()
	{
		groups.clear();

		final String json = configManager.getConfiguration(LootLabelsConfig.GROUP, CONFIG_KEY);
		if (json != null && !json.isEmpty())
		{
			try
			{
				final LabelGroup[] loaded = gson.fromJson(json, LabelGroup[].class);
				if (loaded != null)
				{
					for (LabelGroup group : loaded)
					{
						if (group != null && group.getName() != null)
						{
							group.migrate();
							groups.add(group);
						}
					}
				}
			}
			catch (JsonParseException e)
			{
				log.warn("Could not read the saved label groups", e);
			}
		}

		rebuildRules();
	}

	synchronized List<LabelGroup> getGroups()
	{
		return new ArrayList<>(groups);
	}

	synchronized LabelGroup addGroup(String name)
	{
		final LabelGroup group = new LabelGroup(name);
		groups.add(group);
		changed();
		return group;
	}

	synchronized void removeGroup(LabelGroup group)
	{
		if (groups.remove(group))
		{
			changed();
		}
	}

	synchronized void renameGroup(LabelGroup group, String name)
	{
		group.setName(name);
		changed();
	}

	/**
	 * Moves a group so it ends up at the given place in the list. The order matters: when an item is in several
	 * enabled groups, the one nearest the top decides how it looks.
	 */
	synchronized void moveGroup(LabelGroup group, int newIndex)
	{
		if (groups.remove(group))
		{
			groups.add(Math.max(0, Math.min(newIndex, groups.size())), group);
			changed();
		}
	}

	synchronized void moveItem(LabelGroup group, ItemEntry entry, int newIndex)
	{
		final List<ItemEntry> entries = group.getEntries();
		if (entries.remove(entry))
		{
			entries.add(Math.max(0, Math.min(newIndex, entries.size())), entry);
			changed();
		}
	}

	/**
	 * Renames a line, keeping its place and its conditions. Other lines may have the same name.
	 *
	 * @return false if the new name was blank
	 */
	synchronized boolean renameItem(LabelGroup group, ItemEntry entry, String name)
	{
		final String key = normalize(name);
		if (key.isEmpty() || !group.getEntries().contains(entry))
		{
			return false;
		}

		entry.setName(capitalize(key));
		changed();
		return true;
	}

	synchronized void setEnabled(LabelGroup group, boolean enabled)
	{
		group.setEnabled(enabled);
		changed();
	}

	/** Requires the line's quantity, GE value or HA value to satisfy a comparison. */
	synchronized void setComparison(ItemEntry entry, ItemConditions.Type type, ItemConditions.Op op, long value)
	{
		final ItemConditions.Comparison comparison = new ItemConditions.Comparison(op, value);
		final ItemConditions existing = entry.getConditions();
		if (existing != null && comparison.sameAs(existing.getComparison(type)))
		{
			return;
		}

		editableConditions(entry).setComparison(type, comparison);
		changed();
	}

	/**
	 * @param stackable true for only stackable items, false for only items that don't stack
	 */
	synchronized void setStackable(ItemEntry entry, boolean stackable)
	{
		final ItemConditions existing = entry.getConditions();
		if (existing != null && existing.getStackable() != null && existing.getStackable() == stackable)
		{
			return;
		}

		editableConditions(entry).setStackable(stackable);
		changed();
	}

	synchronized void clearCondition(ItemEntry entry, ItemConditions.Type type)
	{
		final ItemConditions existing = entry.getConditions();
		if (existing == null || !existing.has(type))
		{
			return;
		}

		existing.clear(type);
		if (existing.isEmpty())
		{
			entry.setConditions(null);
		}
		changed();
	}

	private ItemConditions editableConditions(ItemEntry entry)
	{
		if (entry.getConditions() == null)
		{
			entry.setConditions(new ItemConditions());
		}
		return entry.getConditions();
	}

	/** Changes the color while it is being picked: labels update right away, but nothing is saved yet. */
	synchronized void previewColor(LabelGroup group, int rgb)
	{
		group.setColor(rgb & 0xFFFFFF);
		rebuildRules();
	}

	synchronized void setIcon(LabelGroup group, String icon)
	{
		group.setIcon(icon == null ? "" : icon);
		changed();
	}

	/**
	 * @param chosen whether the user actually picked this color, so the sidebar can show it
	 */
	synchronized void setColor(LabelGroup group, int rgb, boolean chosen)
	{
		group.setColor(rgb & 0xFFFFFF);
		if (chosen)
		{
			group.setColorChosen(true);
		}
		changed();
	}

	/** Collapsing only affects the sidebar, so the label rules don't need rebuilding. */
	synchronized void setCollapsed(LabelGroup group, boolean collapsed)
	{
		group.setCollapsed(collapsed);
		save();
	}

	/**
	 * Adds a line at the bottom of the group. A group may have several lines for the same item.
	 *
	 * @return false if the name was blank
	 */
	synchronized boolean addItem(LabelGroup group, String item)
	{
		final String key = normalize(item);
		if (key.isEmpty())
		{
			return false;
		}

		group.getEntries().add(new ItemEntry(capitalize(key)));
		changed();
		return true;
	}

	synchronized void removeItem(LabelGroup group, ItemEntry entry)
	{
		if (group.getEntries().remove(entry))
		{
			changed();
		}
	}

	/**
	 * Decides how a ground item is labelled. A group's entry for an item only counts if the item meets the entry's
	 * conditions. The item gets the style of the first enabled group (in list order) with an entry that counts. If
	 * it only has entries in disabled groups it is hidden, and if it has no entry that counts it is drawn plain
	 * when showUngrouped is set, or hidden.
	 *
	 * @return the style, or null if the item should not be labelled
	 */
	LabelStyle styleFor(GroundLabel label, boolean showUngrouped)
	{
		return rules.styleFor(label, showUngrouped);
	}

	/** The JSON that gets copied to the clipboard when the given groups are exported. */
	synchronized String exportJson(List<LabelGroup> selected)
	{
		return GroupTransfer.export(gson, selected);
	}

	/** Reads groups out of exported text; empty when the text holds none. See {@link GroupTransfer#parse}. */
	List<LabelGroup> parseImport(String text)
	{
		return GroupTransfer.parse(gson, text);
	}

	/**
	 * Adds groups produced by {@link #parseImport(String)} after the existing ones.
	 */
	synchronized void importGroups(List<LabelGroup> imported)
	{
		if (!imported.isEmpty())
		{
			groups.addAll(imported);
			changed();
		}
	}

	private void changed()
	{
		rebuildRules();
		save();
	}

	private void save()
	{
		configManager.setConfiguration(LootLabelsConfig.GROUP, CONFIG_KEY, gson.toJson(groups));
	}

	private void rebuildRules()
	{
		rules = new Rules(groups);
	}

	/** Immutable lookup built from the groups. Entries containing * are wildcards, e.g. "*bones". */
	private static final class Rules
	{
		private final Map<String, List<Entry>> exactEntries = new HashMap<>();
		private final List<Entry> patternEntries = new ArrayList<>();

		Rules(List<LabelGroup> groups)
		{
			int order = 0;
			for (LabelGroup group : groups)
			{
				final LabelStyle style = LabelStyle.ofGroup(group.getColor(), RankIcons.image(group.getIcon()));
				for (ItemEntry item : group.getEntries())
				{
					final String key = normalize(item.getName());
					if (key.isEmpty())
					{
						continue;
					}

					final ItemConditions conditions = item.getConditions();
					final ItemConditions snapshot = conditions == null ? null : conditions.copy();
					if (key.indexOf('*') >= 0)
					{
						patternEntries.add(new Entry(toPattern(key), style, order, group.isEnabled(), snapshot));
					}
					else
					{
						exactEntries.computeIfAbsent(key, k -> new ArrayList<>())
							.add(new Entry(null, style, order, group.isEnabled(), snapshot));
					}
				}
				order++;
			}
		}

		LabelStyle styleFor(GroundLabel label, boolean showUngrouped)
		{
			final String key = label.getKey();
			Entry best = null;
			boolean listed = false;

			final List<Entry> exact = exactEntries.get(key);
			if (exact != null)
			{
				for (Entry entry : exact)
				{
					if (entry.applies(label))
					{
						listed = true;
						best = better(best, entry);
					}
				}
			}

			for (Entry entry : patternEntries)
			{
				if (entry.pattern.matcher(key).matches() && entry.applies(label))
				{
					listed = true;
					best = better(best, entry);
				}
			}

			if (best != null)
			{
				return best.style;
			}
			return showUngrouped && !listed ? LabelStyle.PLAIN : null;
		}

		/** Of two entries, the enabled one from the earlier group. */
		private static Entry better(Entry best, Entry entry)
		{
			if (!entry.enabled)
			{
				return best;
			}
			return best == null || entry.order < best.order ? entry : best;
		}

		private static Pattern toPattern(String key)
		{
			final StringBuilder regex = new StringBuilder();
			final String[] parts = key.split("\\*", -1);
			for (int i = 0; i < parts.length; i++)
			{
				if (i > 0)
				{
					regex.append(".*");
				}
				if (!parts[i].isEmpty())
				{
					regex.append(Pattern.quote(parts[i]));
				}
			}
			return Pattern.compile(regex.toString());
		}

		private static final class Entry
		{
			private final Pattern pattern; // null for an exact name
			private final LabelStyle style;
			private final int order;
			private final boolean enabled;
			private final ItemConditions conditions;

			Entry(Pattern pattern, LabelStyle style, int order, boolean enabled, ItemConditions conditions)
			{
				this.pattern = pattern;
				this.style = style;
				this.order = order;
				this.enabled = enabled;
				this.conditions = conditions;
			}

			boolean applies(GroundLabel label)
			{
				return conditions == null || conditions.matches(label);
			}
		}
	}
}

package com.lootlabels;

import java.awt.Color;
import java.awt.image.BufferedImage;

/**
 * How a ground item label is drawn. A label that belongs to a group gets a box in the group's color: a border and a
 * fill of that color (their opacity and the border's thickness come from the settings). A label that is in no group is
 * drawn as plain text.
 */
final class LabelStyle
{
	static final LabelStyle PLAIN = new LabelStyle(null, null, null);

	static final int FILL_ALPHA = 0xB7;

	private final Color border;
	private final Color fill;
	private final BufferedImage icon;

	private LabelStyle(Color border, Color fill, BufferedImage icon)
	{
		this.border = border;
		this.fill = fill;
		this.icon = icon;
	}

	/**
	 * @param rgb the group's color as 0xRRGGBB
	 * @param icon drawn left of the text inside the box, or null for none
	 */
	static LabelStyle ofGroup(int rgb, BufferedImage icon)
	{
		return new LabelStyle(new Color(rgb & 0xFFFFFF),
			new Color((rgb >> 16) & 0xFF, (rgb >> 8) & 0xFF, rgb & 0xFF, FILL_ALPHA), icon);
	}

	boolean isBoxed()
	{
		return border != null;
	}

	Color getBorder()
	{
		return border;
	}

	Color getFill()
	{
		return fill;
	}

	BufferedImage getIcon()
	{
		return icon;
	}
}

